------------ import ------------
local KTool = CS.Engine.Lib.KTool
------------ import ------------

------------ define ------------
---@type MaidCoffeePlayerComponent
local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule
------------ define ------------

---@class HomeOrderPanel
local HomeOrderPanel = Class('HomeOrderPanel')

function HomeOrderPanel:__init()
    self.DescGroupRoot = nil
    self.deliveryEffect = nil
    self.descriptionText = nil
    self.status = 1
end

function HomeOrderPanel:__delete()
    self.DescGroupRoot = nil
    self.deliveryEffect = nil
    self.descriptionText = nil
    self.DescGroupBg = nil
    self.isVipOrderUnlock = false
    self.status = 0
end

function HomeOrderPanel:Awake()
    self.DescGroupRoot = self.controller.transform:Find("DescGroupRoot")
    self.DescGroupBg = self.DescGroupRoot:Find("DescGroup")
    self.deliveryEffect = self.DescGroupRoot:Find("UIFX_Delivery")
    self.descriptionText = self.DescGroupRoot:Find("DescGroup/MaskText/TxtDesc")
end

function HomeOrderPanel:FreshState()
    local isTakeOutUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3003)
    self.isVipOrderUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3004)
    KTool.SetActive(self.DescGroupRoot.gameObject, isTakeOutUnLock)
    if isTakeOutUnLock then
        local haveFinishOrder = maidCoffeePlayerComponent:IsHasFinishOrder()
        local haveIdleTeam = maidCoffeePlayerComponent:IsHasIdleTeam()
        CfUtils.SetActive(self.deliveryEffect, haveFinishOrder)
        local isTakeout = haveFinishOrder or haveIdleTeam
        if not isTakeout then
            KTool.SetActive(self.DescGroupRoot.gameObject, self.isVipOrderUnlock)
        end
        self:FillOrdersInfo()
    end
end

function HomeOrderPanel:GetOrderStatus()
    local isHas = maidCoffeePlayerComponent:IsHasFinishOrder()
    if isHas then
        return localize("外卖已送达"), 1
    end
    isHas = maidCoffeePlayerComponent:IsHasIdleTeam()
    if isHas then
        return localize("车队空闲中"), 2
    end
    if self.isVipOrderUnlock then
        KTool.SetActive(self.DescGroupRoot.gameObject, self.isVipOrderUnlock)
        local vipOrderId, time = maidCoffeePlayerComponent:GetVipOrderTime()
        if checkNumber(vipOrderId) == 0 or time <= 0 then
            return localize("猫车等待装箱"), 1
        end
        return localize("下一趟猫车:")..CfUtils.GetTimeHMS(time), 3
    end
end

function HomeOrderPanel:FillOrdersInfo()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
    end
    local str, status = self:GetOrderStatus()
    if str then
        CfUtils.FillText(self.descriptionText, str)
        CfUtils.SetUISwitchImage(self.DescGroupBg, status)
    end
    self._timeDown = nil
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id, Elapsed)
        local str, status = self:GetOrderStatus()
        if self.status ~= status then
            self.status = status
            ---@type UIActionPromptUpItemNode
            local scr = CfUtils.GetLuaScr(self.descriptionText.transform.parent.gameObject, "Game.UI.FightReady.UIMainChapter.UIActionPromptUpItemNode")
            if scr then
                scr:Refresh(str, false)
            end
        end
        CfUtils.FillText(self.descriptionText, str)
        CfUtils.SetUISwitchImage(self.DescGroupBg, status)
    end, CountDownTime, false, true)
end



function HomeOrderPanel:OnDestroy()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
    end
    self._timeDown = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return HomeOrderPanel